import re

_POSTCODE_PATTERN = re.compile(r"[1-9]\d{3} ?[A-Za-z]{2}")
_INVALID_LETTER_PAIRS = {"SA", "SD", "SS"}


def is_valid_postcode(s: str) -> bool:
    if not isinstance(s, str):
        return False

    if not _POSTCODE_PATTERN.fullmatch(s):
        return False

    return s[-2:].upper() not in _INVALID_LETTER_PAIRS

def dedupe(listings: list[dict]) -> list[dict]:
    def normalize_title(title: str) -> str:
        return " ".join(title.lower().split())

    best_index: dict[tuple[str, int], int] = {}
    best_date: dict[tuple[str, int], str] = {}

    for index, listing in enumerate(listings):
        key = (normalize_title(listing["title"]), listing["price"])
        date = listing["date"]

        if key not in best_index:
            best_index[key] = index
            best_date[key] = date
        elif date < best_date[key]:
            best_index[key] = index
            best_date[key] = date

    return [listings[index] for index in sorted(best_index.values())]

def add_tag(tag, tags=[]):
    tags = list(tags)
    if tag not in tags:
        tags.append(tag)
    return sorted(tags)

import csv
import io
from decimal import Decimal, InvalidOperation


def totals_by_payment(csv_text: str) -> dict[str, int]:
    totals: dict[str, Decimal] = {}

    if not csv_text:
        return totals

    text = csv_text.lstrip("\ufeff")
    reader = csv.DictReader(io.StringIO(text), skipinitialspace=True)

    if reader.fieldnames:
        reader.fieldnames = [(name or "").strip() for name in reader.fieldnames]

    for row in reader:
        price_raw = row.get("price")
        payment_raw = row.get("payment")

        if price_raw is None or payment_raw is None:
            continue

        price_clean = "".join(price_raw.replace(",", "").split())
        if not price_clean:
            continue

        payment = payment_raw.strip().lower()
        if not payment:
            continue

        try:
            price = Decimal(price_clean)
        except InvalidOperation:
            continue

        if not price.is_finite():
            continue

        totals[payment] = totals.get(payment, Decimal(0)) + price

    return {payment: int(total) for payment, total in totals.items()}

import time

def retry(fn, attempts=3, exceptions=(Exception,), sleep=time.sleep, base_delay=1.0):
    for i in range(attempts):
        try:
            return fn()
        except exceptions:
            if i == attempts - 1:
                raise
            sleep(base_delay * (2 ** i))
